import JSZip from 'jszip';

/** Layout original descompuesto en componentes OpenXML, no se distribuye ningún .xlsx.
 * Mantiene las 7 hojas, formatos, márgenes, fórmulas y opciones de impresión.
 * El vínculo se resuelve contra la Excel maestra de la misma fecha y carpeta.
 */
const parts: ReadonlyArray<readonly [string, string]> = [
  ['[Content_Types].xml', ''],
  ['_rels/.rels', ''],
  ['xl/_rels/workbook.xml.rels', ''],
  ['xl/workbook.xml', ''],
  ['xl/worksheets/sheet4.xml', ''],
  ['xl/worksheets/sheet3.xml', ''],
  ['xl/drawings/vmlDrawing7.vml', ''],
  ['xl/drawings/vmlDrawing6.vml', ''],
  ['xl/worksheets/sheet1.xml', ''],
  ['xl/drawings/vmlDrawing4.vml', ''],
  ['xl/worksheets/sheet2.xml', ''],
  ['xl/worksheets/_rels/sheet1.xml.rels', ''],
  ['xl/worksheets/_rels/sheet2.xml.rels', ''],
  ['xl/worksheets/_rels/sheet7.xml.rels', ''],
  ['xl/worksheets/_rels/sheet6.xml.rels', ''],
  ['xl/worksheets/_rels/sheet5.xml.rels', ''],
  ['xl/worksheets/_rels/sheet4.xml.rels', ''],
  ['xl/worksheets/_rels/sheet3.xml.rels', ''],
  ['xl/drawings/vmlDrawing3.vml', ''],
  ['xl/drawings/vmlDrawing5.vml', ''],
  ['xl/styles.xml', ''],
  ['xl/theme/theme1.xml', ''],
  ['xl/drawings/vmlDrawing1.vml', ''],
  ['xl/drawings/vmlDrawing2.vml', ''],
  ['xl/worksheets/sheet7.xml', ''],
  ['xl/worksheets/sheet6.xml', ''],
  ['xl/worksheets/sheet5.xml', ''],
  ['xl/sharedStrings.xml', ''],
  ['docProps/app.xml', ''],
  ['xl/comments3.xml', ''],
  ['xl/externalLinks/externalLink1.xml', ''],
  ['docProps/core.xml', ''],
  ['xl/externalLinks/_rels/externalLink1.xml.rels', ''],
  ['xl/printerSettings/printerSettings1.bin', ''],
  ['xl/calcChain.xml', ''],
  ['xl/comments7.xml', ''],
  ['xl/printerSettings/printerSettings5.bin', ''],
  ['xl/comments4.xml', ''],
  ['xl/comments2.xml', ''],
  ['xl/printerSettings/printerSettings4.bin', ''],
  ['xl/comments5.xml', ''],
  ['xl/printerSettings/printerSettings6.bin', ''],
  ['xl/printerSettings/printerSettings2.bin', ''],
  ['xl/comments6.xml', ''],
  ['xl/printerSettings/printerSettings7.bin', ''],
  ['xl/comments1.xml', ''],
  ['xl/printerSettings/printerSettings3.bin', ''],
];

function decodeBase64(value: string): Uint8Array {
  const raw = atob(value);
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);
  return bytes;
}

function dateParts(fecha: string): { shortDate: string; longDate: string } {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) throw new Error('Fecha de huelga no válida.');
  const [year, month, day] = fecha.split('-');
  return { shortDate: `${day}-${month}-${year.slice(-2)}`, longDate: `${day}-${month}-${year}` };
}

function escapeXml(value: string): string {
  return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
}

export async function downloadHuelgaGroupedReport(fecha: string): Promise<void> {
  const { shortDate, longDate } = dateParts(fecha);
  const masterName = `Seguimiento huelga ${longDate} general.xlsx`;
  const zip = new JSZip();
  for (const [path, encoded] of parts) {
    let content: string | Uint8Array = decodeBase64(encoded);
    if (path.endsWith('.xml') || path.endsWith('.rels')) {
      const xml = new TextDecoder().decode(content);
      if (path === 'xl/externalLinks/_rels/externalLink1.xml.rels') {
        // El archivo maestro debe encontrarse junto al informe agrupado.
        content = xml.replace(/Target="[^"]*"(?= TargetMode="External")/, `Target="${escapeXml(encodeURIComponent(masterName))}"`);
      } else if (path === 'xl/externalLinks/externalLink1.xml') {
        // Conservar la estructura y los tipos de las celdas de la caché externa.
        // Vaciar sheetDataSet provoca reparaciones de Excel en externalLink1.xml.
        // La actualización de vínculos y el recálculo sustituyen los valores de ejemplo.
        content = xml.replace(/<sheetName val="17-03-26"\s*\/>/, `<sheetName val="${escapeXml(shortDate)}"/>`);
      } else if (path === 'xl/workbook.xml') {
        content = xml.replace(/<x15ac:absPath[^>]*\/>/g, '')
          .replace(/<calcPr\b[^>]*\/>/, '<calcPr calcId="191029" fullCalcOnLoad="1" forceFullCalc="1"/>');
      } else if (/^xl\/worksheets\/sheet\d+\.xml$/.test(path)) {
        content = xml.replace(/17-03-26/g, shortDate).replace(/17\/03\/2026/g, longDate.replace(/-/g, '/'));
        // No eliminar los valores cacheados de las fórmulas: Excel necesita
        // conservar sus tipos y estructura para abrir el libro sin reparaciones.
      } else {
        content = xml.replace(/17-03-26/g, shortDate).replace(/17-03-2026/g, longDate);
      }
    }
    zip.file(path, content);
  }
  const result = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE' });
  const href = URL.createObjectURL(result);
  const anchor = document.createElement('a');
  anchor.href = href;
  anchor.download = `Informe agrupado seguimiento ${shortDate}.xlsx`;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(href);
}
